/**
 * Extracts the Bloub avatar frames used by the website from the app's own
 * source of truth (src/components/bloubFrames.ts).
 *
 * The frames are generated by the vendored Bloub engine (MIT, Jérémy Perret).
 * We never re-draw an avatar by hand: the site renders the same geometry the
 * desktop app renders.
 *
 * Needs esbuild, which comes with Vite.
 *
 * Usage: node site/tools/extract-bloub.mjs
 */
import { build } from 'esbuild';
import { mkdir, stat, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '../..');

const result = await build({
  entryPoints: [resolve(root, 'src/components/bloubFrames.ts')],
  bundle: true,
  format: 'esm',
  write: false,
  platform: 'neutral',
  target: 'es2020',
});

const module = await import(
  'data:text/javascript;base64,' +
    Buffer.from(result.outputFiles[0].text).toString('base64')
);

const { BLOUB_FRAMES, BLOUB_SHAPES } = module;

const frames = {};
for (const shape of BLOUB_SHAPES) {
  const source = BLOUB_FRAMES[shape];
  frames[shape] = {
    viewBox: source.viewBox,
    variants: Object.fromEntries(
      Object.entries(source.variants).map(([variant, frame]) => [
        variant,
        {
          bodyPath: frame.bodyPath,
          eyes: frame.eyes.map((eye) => ({
            d: eye.d,
            matrix: eye.matrix,
            alpha: eye.alpha,
          })),
        },
      ])
    ),
  };
}

const out = resolve(root, 'site/assets/bloub.js');
await mkdir(dirname(out), { recursive: true });
await writeFile(
  out,
  `/* Generated by site/tools/extract-bloub.mjs. Do not hand-edit.\n` +
    `   Frame geometry from src/components/bloubFrames.ts (Bloub, MIT, Jeremy Perret). */\n` +
    `window.BLOUB_FRAMES = ${JSON.stringify(frames)};\n`,
  'utf8'
);

const bytes = (await stat(out)).size;
console.log(
  `bloub.js written: ${BLOUB_SHAPES.length} shapes x ${Object.keys(frames[BLOUB_SHAPES[0]].variants).length} variants, ${(bytes / 1024).toFixed(1)} kB`
);
